from pathlib import Path
import csv,json
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
b=next(Path('../ReviewerComments/FCDTM_无目标真标签分支').glob('U8*'))/'diagnostics/GBC_近零分数核查';a=b/'artifacts';f=b/'figures';f.mkdir(exist_ok=True);v=json.loads((a/'verification.json').read_text());p=json.loads((a/'paired_summary.json').read_text());rows=list(csv.DictReader((a/'grouping_comparison.csv').open()));q=[r for r in rows if r['kind']=='batch4' and np.isfinite(float(r['PL_score'])) and np.isfinite(float(r['GT_score']))];x=np.log10([-float(r['PL_score']) for r in q]);y=np.log10([-float(r['GT_score']) for r in q]);fig,axs=plt.subplots(1,2,figsize=(10,4));bins=np.linspace(min(x.min(),y.min())-1,0,30);axs[0].hist(x,bins=bins,alpha=.65,label='Pseudo-label groups');axs[0].hist(y,bins=bins,alpha=.65,label='Reference-label groups');axs[0].set_xlabel('log10 of absolute native GBC score');axs[0].set_ylabel('Matched four-image batches');axs[0].legend();axs[1].scatter(x,y,s=13,alpha=.6);lo=min(x.min(),y.min())-1;axs[1].plot([lo,0],[lo,0],'--',color='grey');axs[1].set_xlabel('log10 |GBC|: pseudo-label groups');axs[1].set_ylabel('log10 |GBC|: reference groups');fig.suptitle('Post-seal diagnostic: same features and pixels, '+str(len(q))+' matched batches');fig.tight_layout()
for ext in ['png','pdf']:fig.savefig(f/('GBC_grouping_diagnostic.'+ext),dpi=180)
plt.close(fig)
text=f'''# GBC-PL近零分数核查\n\n## 结论\n\n当前没有证据表明近零现象由算术错误或指数下溢造成。它符合GBC的指数形式，并在伪标签分组下明显加重；因此PL适配具有真实的解释限制，不能据其结果否定原有真标签GBC。\n\n## 数值核查\n\n2354个有限四图批次分数中，精确零为0个，2060个绝对值小于0.001（约87.5%），绝对值中位数4.22e-9；原生分数范围约[-0.626,-7.48e-83]。图中采用AD方向的-GBC，因此显示为接近零的正数。GBC分数不是精度。\n\n独立按逐类均值和直接总体方差重算50任务第一个种子的批次及完整40图池，共550条，最大绝对误差{v['independent_score_max_absolute_error']:.3g}，并使用严格相对容差核验微小分数。方差下限1e-4、64维球形协方差、二分类有序类对负和保持一致。未修改评分或统计方向。\n\n当前二分类原生定义为 GBC=-2 exp(-D_B)。当D_B=20时，GBC约-4.12e-9；D_B=50时约-3.86e-22，都是合法的非零数。64维均值/方差项累计可使距离变大。当前2354记录没有精确零，最小量级也远高于float64下溢阈值。\n\n## 同像素、同特征、仅改变分组的对照\n\n真实标签在现有分数封存后才读取，只用于诊断，不参与新评分、调参或选方向。缺失类的诊断记录保留为N/A。以下只比较两版都可定义的419个批次，消除支持集合不同的影响：\n\n|分组|绝对分数中位数|绝对值<0.001|\n|---|---:|---:|\n|模型自身硬伪标签|{p['PL_median_abs']:.3g}|{p['PL_below1e_3']}/419|\n|真实标签|{p['GT_median_abs']:.3g}|{p['GT_below1e_3']}/419|\n\n其中360/419批次的伪标签分组距离更大，即其GBC更接近零。这支持伪标签分组强化了表观分离的解释，但不证明其唯一原因。\n\n模型自身的分类头根据这些特征分组；把它预测的前景和背景当成标签，会形成较容易由模型区分的两组。即使分错了地物，这两组仍可能在模型特征中分离。真实标签分组则会把这些误报和漏报纳入对应真实类，常使两组重叠更多。GBC-PL因此可能对错误模型也给出接近“高可分性”的分数。\n\n同条件真标签诊断仍有258/419批次接近零，因此不能说真实标签条件下绝不出现。原论文旧图的目标图池、特征处理、像素使用和实现环境未完全固定为本轮条件，不能仅按两版图的视觉差异归因。\n\n## 论文应如何处理\n\n保留GBC-PL及原始相关性，明确它是自伪标签适配。不要按表现更改GBC公式、方差下限或逐任务符号。可以另外用对数/对称对数横轴改善显示，但坐标变换与重新定义分数必须区分；用-log(-GBC)替换原分数会改变Pearson，不能当作原GBC结果。该诊断宜作为无标签适配的局限证据，不作为FCDTM优于原版GBC的证明。\n\n代码和逐条数据见code/audit_gbc.py、artifacts/grouping_comparison.csv；验证标签仅在既有U8封存后读取。\n'''
(b/'实验结果分析.md').write_text(text)
print(p)
